// Compact descriptions still specify actual ports, direction, and independent branches.
function view(id,title,parts,edges,explanation,extra={}){
 const list=parts.map(([key,ref,type,x,z,label,tip])=>P(key,ref,type,x,z,label,tip));
 const nets=edges.map(([name,from,to,bits=1,role='data',why=''])=>N(name,from,to,bits,role,why));
 plate(id,title,list,nets,explanation.map(([t,b,ps=[],ns=[]])=>S(t,b,ps,ns)),extra);
}
